mapper.select:
SELECT t.id, t.title, t.status, t.priority, t.plan_start_time, t.plan_end_time, t.start_time, t.end_time, -- 计算是否逾期： -- 1. 没有计划结束时间：不算逾期 -- 2. 已完成（status=4）：比较实际完成时间(end_time)和计划结束时间 -- 3. 未完成：比较当前时间和计划结束时间 CASE WHEN t.plan_end_time IS NULL THEN FALSE WHEN t.status = 4 THEN CASE WHEN t.end_time IS NOT NULL AND t.end_time > t.plan_end_time THEN TRUE ELSE FALSE END WHEN NOW() > t.plan_end_time THEN TRUE ELSE FALSE END AS is_overdue, ( SELECT MAX(tr.create_time) FROM task_record tr WHERE tr.task_id = t.id AND tr.action_type = 1 ) AS latest_submit_time, -- 负责人信息（taskRole = 1 表示负责人） owner_su.user_id AS owner_user_id, owner_su.avatar AS owner_avatar, owner_su.nick_name AS owner_nick_name FROM task t -- 关联负责人 LEFT JOIN task_user owner_tu ON owner_tu.task_id = t.id AND owner_tu.task_role = 1 LEFT JOIN sys_user owner_su ON owner_su.user_id = owner_tu.user_id AND owner_su.del_flag = 0
t.del_flag = 0
AND t.title LIKE CONCAT('%', #{query.title}, '%')
AND t.status = #{query.status}
AND t.priority = #{query.priority}
AND EXISTS ( SELECT 1 FROM task_user filter_tu WHERE filter_tu.task_id = t.id AND filter_tu.user_id = #{query.userId} )
AND t.start_time >= #{query.startTime}
AND t.end_time <= #{query.endTime}
ORDER BY t.create_time DESC

SELECT COUNT(1)
FROM task_user tu
WHERE tu.task_id = #{taskId}
  AND tu.user_id = #{userId}
